<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Forms;

use Override;
use Psr\Http\Message\ResponseInterface;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Theme\Application\DecorateHtml;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\OAuth\Authentication\Application\AuthenticateUser;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepName;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\OAuth\Consent\Application\Usecase\TermsOfUseConsentUsecase;
use Civi\Lughauth\Features\OAuth\Consent\Domain\TermsOfUseAcceptance;
use Civi\Lughauth\Features\OAuth\Consent\Application\Usecase\GdprConsentUsecase;
use Civi\Lughauth\Features\OAuth\Consent\Domain\GdprConsentPurposeItem;
use Civi\Lughauth\Shared\Infrastructure\Translation\MessageProvider;

/**
 * Login step form that presents combined Terms-of-Use and GDPR consent to the authenticated user.
 *
 * This form is triggered when TermsOfUseConsentUsecase reports that the user has not yet
 * accepted the current version of the tenant's terms of service. It displays the full
 * terms text inside a readonly textarea together with an acceptance checkbox. In addition,
 * any GDPR processing purposes that are still pending (as reported by GdprConsentUsecase)
 * are rendered below the terms as a list of individually checkable items, each with an
 * expandable description.
 *
 * On submission, acceptance of the terms and the individual GDPR decisions are stored in a
 * single atomic operation. The IP address and User-Agent are captured for the GDPR audit
 * trail. If the user does not tick the acceptance checkbox the flow throws a LoginException
 * with a must_accept_condition error, re-presenting the consent page.
 *
 * Relationships: delegates consent storage to TermsOfUseConsentUsecase and GdprConsentUsecase,
 * calls AuthenticateUser for post-consent pre-authentication, and relies on HtmlSecurer and
 * DecorateHtml for rendering.
 */
class TermsAndGdprConsentForm implements StepForm
{
    public function __construct(
        private readonly MessageProvider $messages,
        private readonly AuthenticateUser $authenticator,
        private readonly TermsOfUseConsentUsecase $publicConsent,
        private readonly GdprConsentUsecase $gdprConsent,
        private readonly DecorateHtml $decorator,
        private readonly HtmlSecurer $securer
    ) {
    }

    /**
     * Renders the consent page showing terms text and GDPR purpose checkboxes.
     *
     * Fetches the first pending terms-of-use consent document and all pending GDPR purposes
     * for the current user, then emits an HTML page with the readonly terms textarea, the
     * acceptance checkbox, and an optional GDPR block.
     */
    #[Override]
    public function render(StepInput $input, ResponseInterface $response, ?AuthenticationResult $error): StepResult
    {
        $locale = '';
        $tenant = $input->context->tenant;
        $challenges = $input->challenges;

        $js = $this->securer->configureScripts([
            $this->securer->addSign("sign")
        ]);
        $translator = $this->messages->messages('forms', $locale, __DIR__ . '/../../Translations');

        $title = $translator->get("consent.title");
        $errorMessage = $error?->errorMessage;
        $error = $errorMessage !== null && $errorMessage !== ''
            ? $translator->get("consent.error-format", [$translator->get('error.' . strtolower($errorMessage))])
            : '';

        $help = $translator->get("consent.help");
        $code = $translator->get("consent.code");
        $send = $translator->get("consent.send");

        $backLabel = $translator->get("consent.back-label");
        $backText = $translator->get(
            "consent.back-text",
            ["<input class=\"inline\" type=\"submit\" value=\"" . $backLabel . "\" />"]
        );
        $pendings = $this->publicConsent->getPendingConsent(
            $tenant,
            $challenges->username ?? '',
            $input->authRequest->audiences
        );

        $pending = $pendings[0];
        $pendingText = html_entity_decode($pending->text);

        $error = $error !== '' ? '<p class="error">' . $error . '</p>' : '';

        $pendingPurposes = $this->gdprConsent->pendingPurposes($tenant, $challenges->username ?? '');
        $gdprBlock = $this->renderGdprBlock($pendingPurposes);

        $step = StepName::CONSENT->value;
        $response->getBody()->write(
            $this->decorator->getFullPage(
                $input->request,
                'Consent',
                $js . <<< HTML
                    <h1>{$title}</h1>
                    <p>{$help}</p>
                    {$error}
                    <form method="POST">
                        <input type="hidden" name="csid" id="sign" />
                        <input type="hidden" name="step" value="{$step}" />
                        <label>{$code}
                            <textarea type="text" name="conditions" id="conditions" readonly>
                                {$pendingText}
                            </textarea>
                        </label>
                        <label>Acept:
                            <input type="checkbox" name="accept" value="accept" />
                        </label>
                        <input type="hidden" name="consent" value="{$pending->id}" />
                        {$gdprBlock}
                        <input class="primary-button" type="submit" value="{$send}" />
                    </form>
                    <form method="POST">
                        <input type="hidden" name="step" value="" />
                        {$backText}
                    </form>
                    HTML,
                $locale,
                'index',
                $tenant
            )
        );
        return StepResult::render($response, $input->challenges);
    }

    /**
     * Records the terms acceptance and all GDPR decisions, then pre-authenticates the user.
     *
     * Stores the accepted terms document via TermsOfUseConsentUsecase and the individual GDPR
     * purpose decisions (keyed by uid) via GdprConsentUsecase, capturing IP and User-Agent for
     * audit purposes. Throws LoginException if the user did not tick the acceptance checkbox.
     */
    #[Override]
    public function authenticate(StepInput $input): StepResult
    {
        $accept = isset($input->body['accept']);
        $consentId = isset($input->body['consent']);
        if ($accept && $consentId) {
            $this->publicConsent->storeAcceptedConsent(
                $input->context->tenant,
                $input->challenges->username ?? '',
                $input->authRequest->audiences,
                new TermsOfUseAcceptance(id: (string) ($input->body['consent'] ?? ''), text: (string) ($input->body['conditions'] ?? ''))
            );

            $this->storeGdprDecisions($input);

            $csid = (string) ($input->body['csid'] ?? '');
            $auth = $this->authenticator->preAuthenticate(
                $input->authRequest,
                $input->challenges,
                $input->context->tenant,
                $input->context->issuer,
                $csid,
                $input->context->state,
                $input->context->nonce
            );
            return StepResult::proceed($auth, $input->challenges);
        }

        throw new LoginException(auth: AuthenticationResult::consentRequired(), message: 'must_accept_condition');
    }

    /**
     * @param GdprConsentPurposeItem[] $purposes
     */
    private function renderGdprBlock(array $purposes): string
    {
        if (!$purposes) {
            return '';
        }

        $items = '';
        foreach ($purposes as $purpose) {
            $key = htmlspecialchars($purpose->key, ENT_QUOTES);
            $title = htmlspecialchars($purpose->title, ENT_QUOTES);
            $description = htmlspecialchars($purpose->description, ENT_QUOTES);
            $requiredMark = $purpose->required ? ' <span class="required-marker">*</span>' : '';
            $items .= <<<HTML
                <li class="scope-item">
                    <label class="scope-label">
                        <input type="checkbox" name="gdpr_purposes[]" value="{$key}" />
                        <strong>{$title}{$requiredMark}</strong>
                    </label>
                    <details class="scope-description">
                        <summary>Descripcion</summary>
                        <p>{$description}</p>
                    </details>
                </li>
                HTML;
        }

        return <<<HTML
            <section class="gdpr-purposes">
                <h3>Propósitos de tratamiento de datos (GDPR)</h3>
                <ul class="scopes-list">
                    {$items}
                </ul>
            </section>
            HTML;
    }

    private function storeGdprDecisions(StepInput $input): void
    {
        $tenant = $input->context->tenant;
        $username = $input->challenges->username ?? '';

        $pendingPurposes = $this->gdprConsent->pendingPurposes($tenant, $username);
        if (!$pendingPurposes) {
            return;
        }

        $checkedKeys = $this->normalizeChecked($input->body['gdpr_purposes'] ?? []);

        $decisions = [];
        foreach ($pendingPurposes as $purpose) {
            $decisions[$purpose->uid] = in_array($purpose->key, $checkedKeys, true);
        }

        $serverParams = $input->request->getServerParams();
        $ipAddress = (string) ($serverParams['REMOTE_ADDR'] ?? '');
        $userAgent = (string) ($input->request->getHeaderLine('User-Agent') ?? '');

        $this->gdprConsent->storePurposeDecisions($tenant, $username, $decisions, $ipAddress, $userAgent);
    }

    /**
     * @return string[]
     */
    private function normalizeChecked(mixed $values): array
    {
        if (is_string($values)) {
            return [$values];
        }
        if (!is_array($values)) {
            return [];
        }
        return array_values(array_filter(array_map('strval', $values)));
    }
}
